module domino_coloring (input clk, input rst_n, input start, input [3:0] s1 [0:15], input [3:0] s2 [0:15], output reg [31:0] result, output reg done); // State reg [2:0] state; // Snapshots reg [3:0] s1_snap [0:15]; reg [3:0] s2_snap [0:15]; // Type sequence reg [1:0] type_seq [0:15]; // Sequence length reg [3:0] seq_length; // Delay counter reg [4:0] delay_counter; // Temporary result reg [31:0] temp_result; // Variables for calculation reg [1:0] prev_type, curr_type; // Done latch reg done_latched; // State parameters localparam IDLE = 3'b000; localparam PARSE = 3'b001; localparam CALCULATE = 3'b010; localparam DONE = 3'b100; // Reset block always @(*) begin state <= IDLE; s1_snap <= 16'b0; s2_snap <= 16'b0; delay_counter <= 5'b0; done_latched <= 1'b0; seq_length <=4'b0; end always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= IDLE; s1_snap <= 16'b0; s2_snap <= 16'b0; delay_counter <= 5'b0; done_latched <= 1'b0; seq_length <=4'b0; end else begin if (start) begin // Capture inputs s1_snap <= s1; s2_snap <= s2; state <= PARSE; end else begin case (state) PARSE: begin // Compute type_seq and seq_length integer i, idx; idx =0; i=0; while (i <16) begin if (s1_snap[i] == s2_snap[i]) begin type_seq[idx] = 2'b10; idx = idx +1; i = i +1; end else begin if (i+1 <16 && s1_snap[i] == s1_snap[i+1]) begin type_seq[idx] = 2'b01; idx = idx +1; i = i +2; end else begin type_seq[idx] = 2'b10; idx = idx +1; i = i +1; end end end seq_length <= idx; state <= CALCULATE; end CALCULATE: begin // Compute temp_result integer j; ans =1; if (seq_length ==0) begin temp_result <=0; end else begin if (type_seq[0] == 2'b10) begin ans =3; end else begin ans =6; end for (j=1; j < seq_length; j++) begin prev_type = type_seq[j-1]; curr_type = type_seq[j]; if (prev_type ==2'b10) begin if (curr_type ==2'b10) begin ans = ans *2; end else begin ans = ans *2; end end else begin if (curr_type ==2'b10) begin ans = ans *1; end else begin ans = ans *3; end end if (ans > 1000000006) ans = ans - 1000000007; end temp_result <= ans; end state <= DONE; delay_counter <= 17; end DONE: begin if (delay_counter ==0) begin done_latched <=1; end if (delay_counter >0) begin delay_counter <= delay_counter -1; end end default: state <= IDLE; endcase end end end // Outputs assign result = temp_result; assign done = done_latched; endmodule